={{ (() => {
  const input = $('Set: Extract & Detect Source').first().json;
  const errMsg = $json.error?.message || $json.error?.description || $json.message || 'FastSaverAPI could not extract audio from this URL';
  return JSON.stringify({
    success: false,
    error: errMsg,
    error_code: 'FASTSAVERAPI_FETCH_FAILED',
    error_stage: 'social_download',
    source_url: input.url || '',
    source: input.source,
    transcriber: input.transcriber,
    timestamp: new Date().toISOString()
  });
})() }}

={{ (() => {
  const input = $('Set: Extract & Detect Source').first().json;
