    success: false,
    error: errMsg,
    error_code: 'RAPIDAPI_FETCH_FAILED',
    error_stage: 'youtube_download',
    api_status: apiStatus,
    http_status: httpCode,
    source_url: input.url || '',
    source: input.source,
    transcriber: input.transcriber,
    timestamp: new Date().toISOString()
  });
})() }}

